// Helper de logout local — extraído pra ser reusado pelos dois caminhos
// (auth e demais endpoints) sem duplicar a lógica do 401.
function maybeForceLogoutOn401(url: string, status: number) {
  if (
    status !== 401 ||
    url.includes('/auth/v1/token') ||
    url.includes('/auth/v1/signup') ||
    url.includes('/auth/v1/otp') ||
    typeof window === 'undefined' ||
    window.__forceLogoutInFlight ||
    window.location.pathname === '/login' ||
    window.location.pathname.startsWith('/auth')
  ) {
    return;
  }
  import('@/hooks/useForceLogoutListener')
    .then(({ forceLocalLogout }) => forceLocalLogout('session_expired'))
    .catch(() => { /* noop */ });
}

// Fetch com timeout + telemetria leve (Fase 4):
// - timeout evita requisições travadas em backend lento
// - telemetria agrega contagem/duração por endpoint para a página /admin/telemetria
//
// IMPORTANTE: chamadas em `/auth/v1/` NÃO recebem AbortController nosso.
// O `@supabase/auth-js` segura um lock durante a request; um abort externo
// derruba o fetch mas deixa o lock preso, e qualquer chamada autenticada
// subsequente trava em "Acquiring an exclusive Navigator LockManager lock
// timed out waiting 10000ms". O navegador já garante seu próprio timeout
// de TCP nesses casos.
const fetchWithTimeout: typeof fetch = async (input, init) => {
  const url = typeof input === 'string' ? input : (input as Request).url;
  const method = (init?.method || (input instanceof Request ? input.method : 'GET') || 'GET').toUpperCase();
  const isAuthCall = url.includes('/auth/v1/');

  // Caminho dedicado ao /auth/v1/: sem AbortController nosso.
  if (isAuthCall) {
    const start = performance.now();
    let status = 0;
    try {
      const res = await fetch(input, init);
      status = res.status;
      maybeForceLogoutOn401(url, status);
      return res;
    } finally {
      recordCall({
        url,
        method,
        status,
        durationMs: performance.now() - start,
        isTimeout: false,
      });
    }
  }

  // Demais endpoints (REST/Edge): timeout de 25 s como antes.
  const timeoutMs = 25000;
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), timeoutMs);

  const externalSignal = init?.signal;
  if (externalSignal) {
    if (externalSignal.aborted) controller.abort();
    else externalSignal.addEventListener('abort', () => controller.abort(), { once: true });
  }

  const start = performance.now();
  let status = 0;
  let isTimeout = false;
  try {
    const res = await fetch(input, { ...init, signal: controller.signal });
    status = res.status;
    maybeForceLogoutOn401(url, status);
    return res;
  } catch (err: any) {
    isTimeout = err?.name === 'AbortError';
    throw err;
  } finally {
    clearTimeout(timer);
    recordCall({
      url,
      method,
      status,
      durationMs: performance.now() - start,
      isTimeout,
    });
  }
};

